// Keys are generated by us, never built from a user-supplied file name.
export function newResourceFileKey(): string {
  return `resources/${crypto.randomUUID()}.pdf`;
}

// Lower-case letters, digits, "-", "_", "." and "/" only; no empty segment (so no leading "/"
// or "//") and no ".." segment. Every driver checks this before touching the disk.
export function isStorageKey(key: string): boolean {
  if (!/^[a-z0-9._/-]+$/.test(key)) return false;
  return key.split("/").every((segment) => segment !== "" && segment !== "..");
}

export function assertStorageKey(key: string): void {
  if (!isStorageKey(key)) throw new Error("Invalid storage key");
}

// A prefix for `list`: the same characters as a key, but it may end in "/" or be empty.
export function assertStoragePrefix(prefix: string): void {
  if (!/^[a-z0-9._/-]*$/.test(prefix) || prefix.split("/").some((segment) => segment === "..")) {
    throw new Error("Invalid storage prefix");
  }
}
